<?php

declare(strict_types=1);

namespace App\Http\Controllers\Auth;

use App\Auth\UserRepository;
use Sahil\Auth\AuthManager;
use Sahil\Contracts\Foundation\ApplicationContract;
use Sahil\Contracts\View\ViewContract;
use Sahil\Http\Request;
use Sahil\Http\Response;
use Sahil\Validation\ValidationException;
use Throwable;

use function Sahil\link;

/**
 * Account creation endpoints generated by `php sahil unda:auth`.
 *
 * A new account is written with a one-way password hash and signed in
 * immediately, so registration lands on the dashboard.
 */
final class RegisterController
{
    public function __construct(
        private readonly ViewContract $views,
        private readonly ApplicationContract $application,
        private readonly AuthManager $auth,
        private readonly UserRepository $users,
    ) {
    }

    public function showRegistrationForm(): Response
    {
        if ($this->auth->check()) {
            return Response::redirect(link('dashboard'), 303);
        }

        return $this->page('auth.register');
    }

    public function register(Request $request): Response
    {
        $data = $request->form()->validate([
            'name' => 'required|string|min:2|max:80',
            'email' => 'required|email|min:3|max:190',
            'password' => 'required|string|password|confirmed',
        ], [
            'name.required' => 'Enter your full name.',
            'name.min' => 'Use between 2 and 80 characters for your name.',
            'name.max' => 'Use between 2 and 80 characters for your name.',
            'email.required' => 'Enter your email address.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.max' => 'That email address is too long.',
            'password.required' => 'Choose a password.',
            'password.password' => 'Use at least 8 characters, including a letter and a number.',
            'password.confirmed' => 'The password confirmation does not match.',
        ], bag: 'register', normalize: 'trim');

        $email = strtolower($data['email']);

        if ($this->users->exists($email)) {
            throw ValidationException::withMessages(
                ['email' => 'An account with that email already exists. Sign in instead.'],
                bag: 'register',
                input: $request->form()->all(),
            );
        }

        try {
            $user = $this->users->create(
                $data['name'],
                $email,
                $data['password'],
            );
        } catch (Throwable) {
            throw ValidationException::withMessages(
                ['email' => 'We could not create that account right now. Please try again.'],
                bag: 'register',
                input: $request->form()->all(),
            );
        }

        $this->auth->login($user);

        // One event, several reactions: a synchronous listener sends the
        // welcome notification (lands in `notifications` for
        // `unreadNotifications()`) and a queued listener records activity.
        if ($user instanceof \Sahil\Contracts\Notifications\NotifiableContract) {
            \Sahil\Events\Event::dispatch(new \App\Events\UserRegistered($user));
        }

        return Response::redirect(link('dashboard'), 303);
    }

    /**
     * @param array<string, mixed> $data
     */
    private function page(string $view, array $data = []): Response
    {
        return Response::html($this->views->render($view, [
            'app_name' => (string) $this->application->config()->get('app.name', 'SahilPHP'),
            'year' => gmdate('Y'),
            ...$data,
        ]));
    }
}
